function source_duplicate($silent_reject, $com, $host, $time, $dest) {
	if( !$silent_reject ) {
		//logtime( "Before flood check" );
		$may_flood = has_level( 'janitor' );

		if (!$may_flood || (!has_level() && (META_BOARD || $_POST['name'] != ''))) {
			if( $com ) {
				// Check for duplicate comments
				$query  = "select sql_no_cache max(time) from `%s` where com='%s' " .
					"and host='%s' " .
					"and time>%d";
				$result = mysql_board_call( $query, SQLLOG, $com, $host, $time - RENZOKU_DUPE );
				if( $ltime = mysql_result( $result, 0, 0 ) ) {
					//check_fail_floodcheck($com);
					$str = sprintf(S_RENZOKU_DUP, sec2hms( ( $ltime + RENZOKU_DUPE ) - $time, false, true ) );
					error( $str, $dest );
				}
				mysql_free_result( $result );
			}

		}
	}
}

duration_php:
function sec2hms($sec, $padTime = false, $showSeconds = false)
{
    $hms = "";
    $hours = intval(intval($sec) / 3600);
	$minutes = intval(intval($sec) / 60);

	if ($hours) {
    $hms .= $padTime
          ? str_pad($hours, 2, "0", STR_PAD_LEFT). " hour"
          : $hours. " hour";
    if( $hours != 1 ) $hms .= 's';

	$hms .= ' ';
	}

	if ($minutes) {
    $minutes = intval(($sec / 60) % 60);

    $hms .= $padTime
			? str_pad($minutes, 2, "0", STR_PAD_LEFT). " minute"
			: $minutes. " minute";
    if( $minutes != 1 ) $hms .= 's';
	}

	$seconds = intval($sec % 60);

	if ($showSeconds && $seconds) {
		$hms .= ' ';
    	$hms .= $padTime
				? str_pad($seconds, 2, "0", STR_PAD_LEFT). " second"
				: $seconds. " second";
		if ($seconds != 1) $hms .= "s";
	}

    return $hms;
}
